<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\Gateway\TenantLoginProviderFilter;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\Gateway\TenantLoginProviderReadGateway;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProvider;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserWriteGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\UserAttributes;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserPasswordVO;
use Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven\UserLoaderAdapter;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedUserData;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\Gateway\DelegateLoginGateway;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\AppleOAuthProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\GitHubOAuthProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\MicrosoftOAuthProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\GoogleOAuthProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\Saml2Provider;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderSourceOptions;

/**
 * Infrastructure adapter that implements DelegateLoginGateway by wiring together
 * tenant-provider configuration, user persistence, and the concrete provider implementations.
 *
 * This class reads the TenantLoginProvider records from the database, translates each
 * enabled record into the matching DelegatedLoginProvider instance (Google, GitHub, Microsoft,
 * Apple, or SAML 2.0), and handles just-in-time user provisioning when a social-login user
 * is seen for the first time. It also fills the pre-authentication challenge state so the
 * session management layer can issue the OIDC tokens after a successful external assertion.
 * Provider credentials (client IDs, secrets, private keys) are retrieved from the tenant
 * configuration and passed directly to the individual provider constructors.
 */
class DelegateLoginAdapter implements DelegateLoginGateway
{
    public function __construct(
        private readonly AppConfig $conf,
        private readonly Context $context,
        private readonly UserLoaderAdapter $userLoader,
        private readonly UserWriteGateway $users,
        private readonly LoginGateway $login,
        private readonly AesCypherService $cypher,
        private readonly TenantLoginProviderReadGateway $loginProviders
    ) {
    }

    /**
     * Looks up or just-in-time provisions the user identified by the provider assertion within
     * the given tenant, fills the pre-authentication challenge state, and returns a populated
     * AuthenticationResult ready for the OIDC token issuance pipeline.
     */
    #[Override]
    public function save(string $tenant, AuthenticationRequest $client, DelegatedUserData $user, string $providerId): AuthenticationResult
    {
        $theTenant = $this->userLoader->checkTenant($tenant, '-');
        $filter = new TenantLoginProviderFilter(
            uids: [ $providerId ],
            tenant: $theTenant
        );
        if (!$existent = $this->loginProviders->retrieve($filter)) {
            throw new NotFoundException('No provider ' . $providerId);
        }
        $prev = $this->users->findOneForUpdateByTenantAndName(
            $theTenant,
            $user->email
        );
        if (!$prev) {
            $enabled = $existent->isUsersEnabledByDefault();
            $attr = new UserAttributes();
            $attr->uid(Random::comb());
            $attr->name($user->email);
            $attr->provider($existent->getSource()->value);
            $attr->tenant($theTenant);
            $attr->password(UserPasswordVO::fromPlainText($this->cypher, Random::password()));
            $prev = $this->users->create(User::create($attr));
            if ($enabled) {
                $this->users->update($prev, $prev->enable());
            }
        }
        $challenges = (new ChallengesState())->withUsername($user->email);
        $this->login->fillPreAuthenticated($tenant, $client, $challenges);
        // Si no existe lo creo
        return new AuthenticationResult(
            valid: true,
            id: $user->email,
            tenant: $tenant,
            tenantName: 'tenantName',
            scope: $client->scope,
            audiences: $client->audiences,
            roles: ['rol-1'],
            groups: ['group-1']
        );
    }

    /**
     * @return DelegatedLoginProvider[]
     *
     * @psalm-return list{0?: DelegatedLoginProvider,...}
     */
    /**
     * Returns all active DelegatedLoginProvider instances configured for the tenant by reading
     * the TenantLoginProvider records and instantiating the corresponding provider class for
     * each enabled entry.
     */
    #[Override]
    public function providers(string $tenant): array
    {
        // La lista de registros de google.
        $providers = [];
        $theTenant = $this->userLoader->checkTenant($tenant, '-');
        $filter = new TenantLoginProviderFilter(
            tenant: $theTenant
        );
        $all = $this->loginProviders->list($filter);
        foreach ($all as $a) {
            if ($a === null) {
                continue;
            }
            if ($provider = $this->loadProvider($a)) {
                $providers[] = $provider;
            }
        }
        return $providers;
    }

    /**
     * Resolves a single DelegatedLoginProvider by tenant and provider ID, throwing
     * NotFoundException when the provider is absent or disabled.
     */
    #[Override]
    public function getProvider(string $tenant, string $id): DelegatedLoginProvider
    {
        $theTenant = $this->userLoader->checkTenant($tenant, '-');
        $filter = new TenantLoginProviderFilter(
            uids: [ $id ],
            tenant: $theTenant
        );
        if ($existent = $this->loginProviders->retrieve($filter)) {
            if ($provider = $this->loadProvider($existent)) {
                return $provider;
            }
        }
        throw new NotFoundException('');
    }

    private function loadProvider(TenantLoginProvider $provider): DelegatedLoginProvider|null
    {
        if ($provider->isDisabled()) {
            return null;
        }

        $saml = $this->readSamlConfig($provider);

        return match ($provider->getSource()) {
            TenantLoginProviderSourceOptions::GOOGLE => new GoogleOAuthProvider(
                $this->conf,
                $this->context,
                $provider->uid() ?? '',
                $provider->getPublicKey() ?? '',
                $provider->getPrivateKey() ?? ''
            ),
            TenantLoginProviderSourceOptions::GITHUB => new GitHubOAuthProvider(
                $this->conf,
                $this->context,
                $provider->uid() ?? '',
                $provider->getPublicKey() ?? '',
                $provider->getPrivateKey() ?? ''
            ),
            TenantLoginProviderSourceOptions::MICROSOFT => new MicrosoftOAuthProvider(
                $this->conf,
                $this->context,
                $provider->uid() ?? '',
                $provider->getPublicKey() ?? '',
                $provider->getPrivateKey() ?? '',
                (string) ($provider->getMetadata() ?? 'common')
            ),
            TenantLoginProviderSourceOptions::APPLE => new AppleOAuthProvider(
                $this->conf,
                $this->context,
                $provider->uid() ?? '',
                $provider->getPublicKey() ?? '',
                (string) ($this->conf->get('apple.team.id', '')),
                (string) ($this->conf->get('apple.key.id', '')),
                (string) ($provider->getPrivateKey() ?? '')
            ),
            TenantLoginProviderSourceOptions::SAML => new Saml2Provider(
                $this->conf,
                $this->context,
                $provider->uid() ?? '',
                (string) ($saml['idp_sso_url'] ?? $provider->getPublicKey() ?? ''),
                (string) ($saml['entity_id'] ?? $provider->getName() ?? 'saml-sp'),
                (string) ($saml['name'] ?? $provider->getName() ?? 'SAML')
            ),
            default => null,
        };
    }

    /**
     * @return array<string, mixed>
     */
    private function readSamlConfig(TenantLoginProvider $provider): array
    {
        $metadata = $provider->getMetadata();
        if (!is_string($metadata) || $metadata === '') {
            return [];
        }
        $decoded = json_decode($metadata, true);
        return is_array($decoded) ? $decoded : [];
    }
}
